def priority(task, state, m=10.0, q_thresh=0.5, k=2.0, age_w=0.5):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    # Queue pressure: fraction of capacity represented by waiting work
    pressure = state.queue_work / max(state.capacity, 1e-6)
    if pressure > q_thresh:
        # Under heavy load, favor short premium jobs strongly (SPT-ish)
        return tier / est * (1.0 + age_w * wait / est)
    # Under light load, use slack-aware ATC to protect due times
    slack = max(0.0, task.due - est - state.now)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return tier * task.weight / est * urgency * (1.0 + age_w * wait / est)

