def priority(task, state, m=10.0, k=3.0, base_spt=1.0, slack_scale=2.0, late_pow=1.5):
    import math
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - est - state.now
    mean_est = max(state.mean_est, 1e-6)
    if slack >= 0:
        urgency = math.exp(-slack / (k * mean_est))
    else:
        urgency = 1.0 + slack_scale * (-slack / mean_est) ** late_pow
    return tier * task.weight * urgency * (base_spt / est)

