def priority(task, state, m=5.0, k=2.0, q_thresh=0.5, q_boost=3.0, late_mult=2.0, type_boost=1.2):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - est - state.now
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / est
    atc = base * math.exp(-max(0.0, slack) / (k * mean))
    if task.task_type == 'reduce':
        atc *= type_boost
    elif task.task_type == 'join':
        atc *= (2.0 - type_boost)
    load = state.queue_work / max(state.capacity, 1e-6)
    if load > q_thresh:
        spt = tier / est
        score = q_boost * spt + atc
    else:
        score = atc
    if slack < 0:
        score *= late_mult
    return score

